'use strict';
// Админка: «Телеграм»
const TG_LOG=DB.telegramLog;
function renderTg(body,tab,fresh){
  if(tab==='log'){const q=TG_LOG.filter(x=>x.st==='Ожидает').length,er=TG_LOG.filter(x=>x.st==='Ошибка').length;
    body.innerHTML=`<div class="plates">${plate({id:'q',icon:'hourglass',color:'yellow',label:'В очереди',value:q,sub:'отправляются пачками'})}${plate({id:'e',icon:'alert',color:er?'red':'green',label:'Ошибки отправки',value:er,sub:'после 5 повторов'})}${plate({id:'s',icon:'send',color:'green',label:'Отправлено сегодня',value:TG_LOG.filter(x=>x.st==='Отправлено'&&x.at.startsWith(TODAY)).length})}</div><div id="tgg"></div>`;
    body.querySelector('.plates').onclick=e=>{const b=e.target.closest('[data-plate]');if(!b)return;const g=GS['tg-log'];if(!g)return;g.filters={};if(b.dataset.plate==='e')g.filters.st={type:'enum',vals:['Ошибка']};if(b.dataset.plate==='q')g.filters.st={type:'enum',vals:['Ожидает']};renderPage()};
    grid($('#tgg',body),{id:'tg-log',audit:false,cols:[{key:'at',label:'Время',type:'text',w:150,val:x=>x.at,text:x=>fmtD(x.at.slice(0,10))+' '+x.at.slice(11),sortVal:x=>x.at},{key:'to',label:'Получатель',type:'text',w:190,val:x=>x.to},{key:'org',label:'Организация',type:'enum',w:220,val:x=>x.org},{key:'kind',label:'Тип сообщения',type:'enum',w:190,val:x=>x.kind},{key:'st',label:'Статус',type:'enum',w:140,val:x=>x.st,html:x=>pill(x.st,{Отправлено:['green','check'],Ожидает:['yellow','hourglass'],Ошибка:['red','alert']})},{key:'tries',label:'Попыток',type:'int',w:90,num:true,val:x=>x.tries},{key:'err',label:'Ошибка',type:'text',w:280,val:x=>x.err,cls:'mono'}],
      rows:()=>TG_LOG,title:'kind',noun:['сообщение','сообщения','сообщений'],sort:{key:'at',dir:-1},rowClass:x=>x.st==='Ошибка'?'overdue':'',simulateLoad:fresh,
      actions:x=>[{label:'Повторить отправку',icon:'refresh',disabled:x.st!=='Ошибка',reason:x.st!=='Ошибка'?'Повтор доступен только для ошибок':'',run:()=>{x.st='Ожидает';x.tries=0;x.err='';renderPage();toast('Сообщение снова в очереди','tg');setTimeout(()=>{x.st='Отправлено';x.tries=1;if(S.mod==='tg')renderPage()},1600)}}],
      bulk:[{label:'Повторить ошибки',icon:'refresh',run:(rs,done)=>{rs.filter(x=>x.st==='Ошибка').forEach(x=>{x.st='Ожидает';x.err=''});done();renderPage();toast('Поставлено в очередь')}}]});return}
  if(tab==='bot'){body.innerHTML=`<div class="cols2"><div class="box"><h3>Бот платформы</h3><div class="kv"><div><span class="k">Имя</span><span class="v mono">@buhuchet_bot</span></div><div><span class="k">Токен</span><span class="v mono">71•••••••:AA•••••••••••••Qk</span></div><div><span class="k">Вебхук</span><span class="v mono" style="font-size:12px">https://buhuchet.kg/api/telegram/webhook</span></div><div><span class="k">Состояние</span><span class="v">${pill('Работает',{Работает:['green','check']})}</span></div></div><div class="row"><button class="btn sm" id="tg-wh">${ic('refresh','sm')}Проверить вебхук</button><button class="btn sm" id="tg-tok">${ic('key','sm')}Заменить токен</button></div></div>
    <div class="box"><h3>Очередь отправки</h3><p style="margin:0;line-height:1.55">Ежедневная задача по расписанию кладёт сообщения в очередь и отправляет их небольшими пачками с паузой, чтобы уложиться в лимиты Telegram и время функции.</p><div class="kv"><div><span class="k">Размер пачки</span><span class="v">25 сообщений</span></div><div><span class="k">Пауза</span><span class="v">1,2 секунды</span></div><div><span class="k">Повторов при ошибке</span><span class="v">5, затем «Ошибка»</span></div><div><span class="k">Сводка</span><span class="v">по понедельникам, 09:00</span></div></div></div></div>`;
    $('#tg-wh',body).onclick=()=>toast(`Вебхук отвечает: 200 OK · проверено ${bishkekNow().hm}`,'check');
    $('#tg-tok',body).onclick=()=>openModal({form:true,render:()=>({title:'Заменить токен бота',sub:'Новый токен выдаёт @BotFather',body:fld('Новый токен',inp('tg-nt','','placeholder="123456789:AA..." autocomplete="off"'),{req:true,id:'tg-nt',hint:'После замены вебхук переустанавливается сам; старый токен перестаёт работать'}),foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="tg-nt-ok">Заменить</button>',
      mount(el,m){$('#tg-nt-ok',el).onclick=()=>{const v=val(el,'tg-nt').trim();if(!setErr(el,'tg-nt',/^\d{6,12}:[\w-]{30,}$/.test(v)?'':'Токен должен выглядеть так: 123456789:AAE… (цифры, двоеточие и не меньше 30 символов)'))return;m.close();toast('Токен заменён, вебхук переустановлен','key')}}})});return}
  body.innerHTML=`<div class="box" style="max-width:720px">${fld('Кому',sel('bc-to',[['all','Всем пользователям платформы'],...ORGS.filter(o=>o.active).map(o=>[o.id,o.name])],'all'),{id:'bc-to'})}${fld('Текст объявления',`<textarea class="inp" id="bc-t" style="min-height:120px" placeholder="Например: 15 ноября с 22:00 до 23:00 плановые работы, платформа будет недоступна."></textarea>`,{req:true,id:'bc-t'})}<div class="row"><span class="hint">Сообщение получат только те, кто привязал Telegram.</span><div class="grow"></div><button class="btn cta" id="bc-go">${ic('send','sm')}Поставить в очередь</button></div></div>`;
  $('#bc-go',body).onclick=()=>{const t=val(body,'bc-t');if(!setErr(body,'bc-t',t?'':'Введите текст'))return;const to=val(body,'bc-to');const n=to==='all'?allUsers().length-1:to==='o1'?EMP.filter(e=>e.tg).length:ORGS.find(o=>o.id===to).staff();for(let i=0;i<Math.min(n,6);i++)TG_LOG.unshift({id:TG_LOG.length+1,at:TODAY+' '+bishkekNow().hm,to:'получатель '+(i+1),org:to==='all'?'Все':orgName(to),kind:'Объявление',st:'Ожидает',tries:0,err:''});$('#bc-t',body).value='';toast(`В очереди: ${n} ${plural(n,'сообщение','сообщения','сообщений')}`,'tg');setTimeout(()=>{TG_LOG.forEach(x=>{if(x.kind==='Объявление'&&x.st==='Ожидает'){x.st='Отправлено';x.tries=1}})},2500)};
}

